// Builds the free-text search index (spec: backend/md/site/header.md) from
// the pages (index.html and frontend/pages). Each page gets one entry from its <title>,
// description and <main data-keywords>; elements with an id and a
// data-search="Title" attribute (optionally data-keywords) get their own
// entry that links to #id. Municipalities are searched at runtime from the
// municipality list, so they are not part of this index.
//
// Output: frontend/functions/search-index.js (generated, do not edit).

import { readdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', '#39': "'", nbsp: ' ' };

function text(html = '') {
  return html
    .replace(/<[^>]+>/g, ' ')
    .replace(/&(amp|lt|gt|quot|#39|nbsp);/g, (_, e) => ENTITIES[e])
    .replace(/\s+/g, ' ')
    .trim();
}

const attr = (tag, name) => tag.match(new RegExp(`\\s${name}="([^"]*)"`))?.[1];

function pageEntries(file, html) {
  const title = text(html.match(/<title>([\s\S]*?)<\/title>/)?.[1]).replace(/^(Kuntatieto|Tasapaino) – /, '');
  const heading = text(html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/)?.[1]);
  const description = attr(html.match(/<meta name="description"[^>]*>/)?.[0] || '', 'content') ||
    text(html.match(/<p class="article__standfirst"[^>]*>([\s\S]*?)<\/p>/)?.[1]);
  const main = html.match(/<main[^>]*>/)?.[0] || '';
  const placeholder = /class="placeholder"/.test(html);

  const entries = [{
    href: file,
    title: file === 'index.html' ? 'Etusivu' : title,
    page: title,
    description: description || '',
    keywords: [attr(main, 'data-keywords'), heading !== 'Ladataan…' ? heading : ''].filter(Boolean).join(' '),
    upcoming: placeholder
  }];

  for (const [tag] of html.matchAll(/<[a-z]+\s[^>]*data-search="[^"]*"[^>]*>/g)) {
    const id = attr(tag, 'id');
    if (!id) continue;
    entries.push({
      href: `${file}#${id}`,
      title: attr(tag, 'data-search'),
      page: title,
      description: '',
      keywords: attr(tag, 'data-keywords') || '',
      upcoming: false
    });
  }
  return entries;
}

// The front page is index.html in the project root, the others are in
// frontend/pages; hrefs are file names, resolved in the browser by pageUrl
// (frontend/functions/paths.js).
export async function buildSearchIndex(frontend) {
  const dir = join(frontend, 'pages');
  const files = (await readdir(dir)).filter((f) => f.endsWith('.html')).sort();
  const entries = [...pageEntries('index.html', await readFile(join(frontend, '..', 'index.html'), 'utf8'))];
  for (const file of files) entries.push(...pageEntries(file, await readFile(join(dir, file), 'utf8')));
  const source =
    '// Generated by backend/functions/search-index.mjs from index.html and frontend/pages. Do not edit.\n' +
    `export default ${JSON.stringify(entries, null, 2)};\n`;
  await writeFile(join(frontend, 'functions', 'search-index.js'), source, 'utf8');
  return entries.length;
}
